"""Self-training loops as non-linear urns.

A generative "model" over K modes is represented by the counts N_1, ..., N_K of
its training data. Each round adds one new data point:

* with probability 1 - lam it is generated by the model itself, sampled with
  sharpening exponent alpha, i.e. mode i is chosen with probability
  N_i^alpha / sum_j N_j^alpha  (sampling at temperature T = 1/alpha);
* with probability lam it is fresh data drawn from a fixed reference
  distribution pi (by default uniform).

Data accumulates (nothing is discarded), so the model at time n is simply the
empirical distribution of all data seen so far. With lam = 0 this is the
classical non-linear (generalised Polya) urn with feedback function x^alpha.
"""

from __future__ import annotations

import numpy as np


def sharpened(counts: np.ndarray, alpha) -> np.ndarray:
    """Return probabilities proportional to counts**alpha along the last axis.

    Computed in log space so that large counts and large alpha do not overflow.
    `alpha` must broadcast against counts[..., 0].
    """
    alpha = np.asarray(alpha, dtype=float)[..., None]
    logw = alpha * np.log(counts)
    logw -= logw.max(axis=-1, keepdims=True)
    w = np.exp(logw)
    return w / w.sum(axis=-1, keepdims=True)


def mean_field_drift(x: np.ndarray, alpha: float, lam: float, pi=None) -> np.ndarray:
    """Drift F(x) = (1 - lam) * g(x) + lam * pi - x of the shares x.

    Here g(x)_i = x_i^alpha / sum_j x_j^alpha. Zeros of F are the candidate
    limits of the shares (stochastic approximation heuristics).
    """
    x = np.asarray(x, dtype=float)
    K = x.shape[-1]
    pi = np.full(K, 1.0 / K) if pi is None else np.asarray(pi, dtype=float)
    return (1 - lam) * sharpened(x, alpha) + lam * pi - x


def critical_lambda(alpha) -> np.ndarray:
    """Mean-field threshold for stability of the uniform state (pi uniform).

    Linearising F at x = (1/K, ..., 1/K) on the simplex gives F'(x) v = ((1 - lam)
    alpha - 1) v for every direction v with sum(v) = 0, for every K. The uniform
    state is therefore linearly stable iff (1 - lam) alpha < 1, i.e.
    lam > 1 - 1/alpha.
    """
    alpha = np.asarray(alpha, dtype=float)
    return np.clip(1.0 - 1.0 / alpha, 0.0, None)


def simulate(
    alpha,
    lam,
    K: int = 3,
    n_steps: int = 10_000,
    n_runs: int = 1,
    init: float = 1.0,
    pi=None,
    record_every: int | None = None,
    seed: int | None = None,
) -> dict:
    """Simulate the self-training loop.

    `alpha` and `lam` may be scalars or arrays; they are broadcast together to a
    batch shape B, and `n_runs` independent runs are simulated for every entry,
    all in one vectorised loop over time.

    Returns a dict with
      "shares": final shares, shape B + (n_runs, K);
      "times", "history": if record_every is given, the recorded times and the
        shares at those times, shape (n_records,) + B + (n_runs, K).
    """
    rng = np.random.default_rng(seed)
    alpha = np.asarray(alpha, dtype=float)
    lam = np.asarray(lam, dtype=float)
    batch = np.broadcast_shapes(alpha.shape, lam.shape) + (n_runs,)
    alpha_b = np.broadcast_to(alpha[..., None], batch)
    lam_b = np.broadcast_to(lam[..., None], batch)
    pi = np.full(K, 1.0 / K) if pi is None else np.asarray(pi, dtype=float)
    pi_cum = np.cumsum(pi)

    counts = np.full(batch + (K,), float(init))
    modes = np.arange(K)
    times, history = [], []
    if record_every:
        times.append(0)
        history.append(counts / counts.sum(axis=-1, keepdims=True))

    for t in range(1, n_steps + 1):
        model_cum = np.cumsum(sharpened(counts, alpha_b), axis=-1)
        fresh = rng.random(batch) < lam_b
        cum = np.where(fresh[..., None], pi_cum, model_cum)
        u = rng.random(batch)
        choice = (u[..., None] > cum[..., :-1]).sum(axis=-1)
        counts += choice[..., None] == modes
        if record_every and (t % record_every == 0 or t < record_every):
            times.append(t)
            history.append(counts / counts.sum(axis=-1, keepdims=True))

    out = {"shares": counts / counts.sum(axis=-1, keepdims=True)}
    if record_every:
        out["times"] = np.array(times)
        out["history"] = np.stack(history)
    return out
